-.6v.1l-.1.1h-.3l-.1-.1h-.3v.1h-.4v-.4h-.1l-.2-.2h-.1l-.2.1h-.5v-.1l-.1-.1h-.4l-.1-.2-.1-.1h-.1l-.2-.1h-.3v.1h-.1v.1h-.3v.1h-1.2l-.2-.1h-.1l-.1-.1h-.2v-.1h-.1l-.2-.2v-.5l.1-.2v-.2h-.1l-.1-.2v.3h-1.6l-.1.1h-.1l-.1.1h-.2l-.1.1h-.1v.1h-.3l-.2.1h-.1l-.2.1v.1h-.2l-.1-.1-.1-.1v-.1h-.1v-.2l-.1-.1v-.1h-.1v-.8h-.1v-.1h-.2v-.1h-.1v-.2h-.1v-.1l-.1-.1-.1-.2h-.1v-.1h-.1v-.1h-.1v-.1h-.1v-.1l-.1-.1-.1-.1v-.1h-.2v-.2h-.1v-.1l-.1-.1v-.3h-.1v-.2h-.1l-.1-.1v-.1h-.1v-.2h-.1v-.5h-.1v-.3l-.1-.1v-.4l-.1-.1-.1-.1v-.1h-.1v-.1h-.1v-.1h-.1l-.1-.1h-.1v-.1h-.1v-.1h-.1l-.1-.1h-.1l-.1-.1v-.1h-.1v-.1h-.1l-.1-.1-.2-.1v-.1h-.2v-.4l.1-.1v-.3l-.1-.1h-.1v-.1h-.3v-.1h-1.8v.2l-.1.1h-.1v.1h-.2l-.2.1h-.1z"/> </a></g></svg>

    <div id="peta-wilayah-tooltip" class="peta-wilayah-tooltip" hidden></div>

    <x-modal name="region-info" :show="false" maxWidth="4xl">
        <div class="p-6">
            <div class="mb-4 border-b pb-2">
                <h3 id="info-nama" class="text-xl font-bold text-gray-800 uppercase"></h3>
            </div>
            <div id="info-detail" class="text-sm text-gray-700"></div>
            <div class="mt-6 flex justify-end">
                <button type="button" x-on:click="$dispatch('close-modal', 'region-info')" class="px-4 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300 font-medium">Tutup</button>
            </div>
        </div>
    </x-modal>

    <x-modal name="program-detail" :show="false" maxWidth="2xl">
