<style>
    .peta-jabar-wrapper > svg {
        width: 100%;
        height: auto;
    }
    .peta-jabar-wrapper a.wilayah path {
        cursor: pointer;
        transition: filter 0.15s ease-in-out, stroke-width 0.15s ease-in-out;
    }
    .peta-jabar-wrapper a.wilayah:hover path {
        filter: brightness(0.85);
    }
    .peta-jabar-wrapper a.wilayah.aktif path {
        stroke: #1e3a8a !important;
        stroke-width: 2 !important;
    }
    /* Elemen "jabar" biasanya garis batas/pulau kecil di luar kab-kota, non-klik */
    .peta-jabar-wrapper a.wilayah[data-kode="jabar"] {
        pointer-events: none;
    }
    .peta-wilayah-tooltip {
        position: fixed;
        z-index: 50;
        pointer-events: none;
        padding: 6px 10px;
        background: #1f2937;
        color: #fff;
        font-size: 12px;
        font-weight: 600;
        line-height: 1.2;
        border-radius: 6px;
        box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
        transform: translate(12px, 12px);
    }
</style>

<script>
// Jumlah program per wilayah, di-preload dari server (key = kode wilayah)
window.regionProgramCounts = @json($programCountByKode ?? []);

document.addEventListener('DOMContentLoaded', function () {
    const wrapper = document.querySelector('.peta-jabar-wrapper');
    if (!wrapper) return;

    const infoNama = document.getElementById('info-nama');
    const infoDetail = document.getElementById('info-detail');
    const tooltip = document.getElementById('peta-wilayah-tooltip');
    const programCounts = window.regionProgramCounts || {};

    // === HEATMAP: hitung skala warna berdasarkan jumlah program ===
    const maxCount = Math.max(1, ...Object.values(programCounts));

    // === KODE UNTUK RENTANG LEGENDA DINAMIS ===
    const legendTicksElement = document.getElementById('legend-ticks');
    if (legendTicksElement) {
        // Tentukan jumlah potongan/segmen (Default: 4 segmen untuk 5 titik angka)
        // Jika maxCount sangat kecil (misal hanya 2 program), sesuaikan agar angka tidak berulang
        const segments = maxCount < 4 ? maxCount : 4; 
        let ticksHTML = '';

        for (let i = 0; i <= segments; i++) {
            // Hitung nilai di titik ini
            const val = Math.round((maxCount / segments) * i);
            // Hitung posisi persentase dari kiri
            const percent = (i / segments) * 100;
            
            // Buat garis indikator kecil (tick) dan angkanya
            ticksHTML += `
            <div class="absolute flex flex-col items-center" style="left: ${percent}%; transform: translateX(-50%);">
                <div class="h-1.5 w-px bg-gray-400 mb-0.5"></div>
                <span>${val}</span>
            </div>`;
        }
        legendTicksElement.innerHTML = ticksHTML;
    }

    function getHeatColor(count) {
        if (!count || count <= 0) return '#f3f4f6'; // abu-abu terang untuk 0 program
        const ratio = Math.min(count / maxCount, 1);
        // interpolasi dari biru muda ke biru utama
        const start = { r: 219, g: 234, b: 254 }; // biru muda
        const end = { r: 37, g: 99, b: 235 };     // biru utama (#2563eb)
        const r = Math.round(start.r + (end.r - start.r) * ratio);
        const g = Math.round(start.g + (end.g - start.g) * ratio);
        const b = Math.round(start.b + (end.b - start.b) * ratio);
        return `rgb(${r}, ${g}, ${b})`;
    }

    wrapper.querySelectorAll('a.wilayah[data-kode]').forEach(function (el) {
        const kode = el.dataset.kode;
        if (kode === 'jabar') return;

        const namaWilayah = el.getAttribute('xlink:title') || el.getAttribute('title') || kode;
        el.removeAttribute('xlink:title');
        el.removeAttribute('title');

        const total = programCounts[kode] ?? 0;
        const warna = getHeatColor(total);
        
        el.style.fill = warna;

        el.addEventListener('mouseenter', function () {
            const total = programCounts[kode] ?? 0;
            tooltip.innerHTML = `<span class="font-semibold">${namaWilayah}</span><br><span class="text-xs text-gray-200">${total} program</span>`;
            tooltip.hidden = false;
        });

        el.addEventListener('mousemove', function (e) {
            tooltip.style.left = `${e.clientX + 12}px`;
            tooltip.style.top = `${e.clientY + 12}px`;
        });

        el.addEventListener('mouseleave', function () {
            tooltip.hidden = true;
        });

        el.addEventListener('click', async function (e) {
            e.preventDefault();

            const kode = this.dataset.kode;
            if (kode === 'jabar') return;

            wrapper.querySelectorAll('a.wilayah').forEach(function (w) {
                w.classList.remove('aktif');
            });
            this.classList.add('aktif');

            try {
                const res = await fetch(`/wilayah/${kode}`);
                if (!res.ok) throw new Error('Data tidak ditemukan');
                const data = await res.json();

                infoNama.textContent = data.nama_wilayah;
                window.regionProgramsData = data.programs || [];
                window.regionInfoText = data.informasi || '';
                window.renderProgramsPage(1);
                window.dispatchEvent(new CustomEvent('open-modal', { detail: 'region-info' }));
            } catch (err) {
                infoNama.textContent = this.getAttribute('xlink:title') || kode;
                infoDetail.innerHTML = '<p class="text-gray-500">Informasi belum tersedia untuk wilayah ini.</p>';
                window.dispatchEvent(new CustomEvent('open-modal', { detail: 'region-info' }));
            }
        });
    }); // <-- penutup forEach
}); // <-- penutup DOMContentLoaded

window.renderProgramsPage = function(page) {
    const data = window.regionProgramsData || [];
    const limit = 5;
    let totalPages = Math.ceil(data.length / limit);
    if (totalPages === 0) totalPages = 1;
    if (page < 1) page = 1;
    if (page > totalPages) page = totalPages;
    
    const start = (page - 1) * limit;
    const end = start + limit;
    const paginatedItems = data.slice(start, end);
    
    const infoDetail = document.getElementById('info-detail');
    let html = window.regionInfoText ? `<p class="mb-4 text-gray-600">${window.regionInfoText}</p>` : '';
    
    if (data.length > 0) {
        html += `<h4 class="font-bold mb-2 text-gray-800">Daftar Program:</h4><ul class="space-y-3 pr-2">`;
        paginatedItems.forEach(p => {
            const formatTanggal = (value, options) => new Intl.DateTimeFormat('id-ID', options).format(new Date(`${value}T00:00:00`));
            let tanggal = '-';
            if (p.tanggal_mulai) {
                const mulai = new Date(`${p.tanggal_mulai}T00:00:00`);
                const selesai = p.tanggal_selesai ? new Date(`${p.tanggal_selesai}T00:00:00`) : null;

                if (!selesai || mulai.getTime() === selesai.getTime()) {
                    tanggal = formatTanggal(p.tanggal_mulai, { day: 'numeric', month: 'long', year: 'numeric' });
                } else if (mulai.getFullYear() === selesai.getFullYear() && mulai.getMonth() === selesai.getMonth()) {
                    tanggal = `${mulai.getDate()} - ${formatTanggal(p.tanggal_selesai, { day: 'numeric', month: 'long', year: 'numeric' })}`;
                } else if (mulai.getFullYear() === selesai.getFullYear()) {
                    tanggal = `${formatTanggal(p.tanggal_mulai, { day: 'numeric', month: 'long' })} - ${formatTanggal(p.tanggal_selesai, { day: 'numeric', month: 'long', year: 'numeric' })}`;
                } else {
                    tanggal = `${formatTanggal(p.tanggal_mulai, { day: 'numeric', month: 'long', year: 'numeric' })} - ${formatTanggal(p.tanggal_selesai, { day: 'numeric', month: 'long', year: 'numeric' })}`;
                }
            }
            

            html += `<li class="p-3 border border-gray-200 bg-gray-50 rounded-md shadow-sm">
                <div class="flex justify-between items-center gap-4">
                    <div>
                        <div class="font-semibold text-gray-800 text-base">${p.nama_program}</div>
                        <div class="text-xs text-gray-500 mt-1">Tanggal: ${tanggal}</div>
                    </div>
                    <div class="flex-shrink-0">
                        <button type="button" onclick="showProgramDetailModal(${p.id}, '${tanggal}')" class="inline-flex items-center px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white text-xs font-semibold rounded-md transition shadow-sm">
                            Detail
                        </button>
                    </div>
                </div>
            </li>`;
        });
        html += `</ul>`;
        
        if (totalPages > 1) {
            html += `<div class="mt-4 border-t border-gray-200 bg-white pt-4 rounded-md">
                <div class="flex justify-between flex-1 sm:hidden">
                    <button type="button" onclick="renderProgramsPage(${page - 1})" ${page === 1 ? 'disabled' : ''} class="relative inline-flex items-center px-4 py-2 text-sm font-medium ${page === 1 ? 'text-gray-500 bg-white border border-gray-300 cursor-default' : 'text-black bg-white border border-gray-300 hover:text-gray-500'} leading-5 rounded-md">
                        Sebelumnya
                    </button>
                    <button type="button" onclick="renderProgramsPage(${page + 1})" ${page === totalPages ? 'disabled' : ''} class="relative inline-flex items-center px-4 py-2 ml-3 text-sm font-medium ${page === totalPages ? 'text-gray-500 bg-white border border-gray-300 cursor-default' : 'text-black bg-white border border-gray-300 hover:text-gray-500'} leading-5 rounded-md">
                        Selanjutnya
                    </button>
                </div>
                <div class="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
                    <div>
                        <p class="text-sm text-black leading-5">
                            Menampilkan <span class="font-medium">${start + 1}</span> sampai <span class="font-medium">${Math.min(end, data.length)}</span> dari <span class="font-medium">${data.length}</span> hasil
                        </p>
                    </div>
                    <div>
                        <span class="relative z-0 inline-flex shadow-sm rounded-md">
                            <button type="button" onclick="renderProgramsPage(${page - 1})" ${page === 1 ? 'disabled' : ''} class="relative inline-flex items-center px-2 py-2 text-sm font-medium ${page === 1 ? 'text-gray-500 bg-white border border-gray-300 cursor-default' : 'text-black bg-white border border-gray-300 hover:text-gray-400 focus:z-10 focus:outline-none focus:ring ring-gray-300 focus:border-blue-300 active:bg-gray-100 active:text-black transition ease-in-out duration-150'} rounded-l-md leading-5" ${page === 1 ? 'aria-disabled="true"' : ''}>
                                <span class="sr-only">Previous</span>
                                <svg class="w-5 h-5" fill="currentColor" viewBox="0 0 20 20" aria-hidden="true">
                                    <path fill-rule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clip-rule="evenodd" />
                                </svg>
                            </button>`;
            
            let maxVisiblePages = 5;
            let startPage = Math.max(1, page - Math.floor(maxVisiblePages / 2));
            let endPage = Math.min(totalPages, startPage + maxVisiblePages - 1);
            
            if (endPage - startPage + 1 < maxVisiblePages) {
                startPage = Math.max(1, endPage - maxVisiblePages + 1);
            }
            
            if (startPage > 1) {
                html += `<button type="button" onclick="renderProgramsPage(1)" class="relative inline-flex items-center px-4 py-2 -ml-px text-sm font-medium text-black bg-white border border-gray-300 leading-5 hover:text-gray-500 focus:z-10 focus:outline-none focus:ring ring-gray-300 focus:border-blue-300 active:bg-gray-100 active:text-black transition ease-in-out duration-150">1</button>`;
                if (startPage > 2) html += `<span class="relative inline-flex items-center px-4 py-2 -ml-px text-sm font-medium text-black bg-white border border-gray-300 cursor-default leading-5">...</span>`;
            }

            for (let i = startPage; i <= endPage; i++) {
                if (i === page) {
                    html += `<span aria-current="page" class="relative inline-flex items-center px-4 py-2 -ml-px text-sm font-medium text-white bg-blue-600 border border-blue-600 cursor-default leading-5">${i}</span>`;
                } else {
                    html += `<button type="button" onclick="renderProgramsPage(${i})" class="relative inline-flex items-center px-4 py-2 -ml-px text-sm font-medium text-black bg-white border border-gray-300 leading-5 hover:text-gray-500 focus:z-10 focus:outline-none focus:ring ring-gray-300 focus:border-blue-300 active:bg-gray-100 active:text-black transition ease-in-out duration-150">${i}</button>`;
                }
            }
            
            if (endPage < totalPages) {
                if (endPage < totalPages - 1) html += `<span class="relative inline-flex items-center px-4 py-2 -ml-px text-sm font-medium text-black bg-white border border-gray-300 cursor-default leading-5">...</span>`;
                html += `<button type="button" onclick="renderProgramsPage(${totalPages})" class="relative inline-flex items-center px-4 py-2 -ml-px text-sm font-medium text-black bg-white border border-gray-300 leading-5 hover:text-gray-500 focus:z-10 focus:outline-none focus:ring ring-gray-300 focus:border-blue-300 active:bg-gray-100 active:text-black transition ease-in-out duration-150">${totalPages}</button>`;
            }

            html += `<button type="button" onclick="renderProgramsPage(${page + 1})" ${page === totalPages ? 'disabled' : ''} class="relative inline-flex items-center px-2 py-2 -ml-px text-sm font-medium ${page === totalPages ? 'text-gray-500 bg-white border border-gray-300 cursor-default' : 'text-black bg-white border border-gray-300 hover:text-gray-400 focus:z-10 focus:outline-none focus:ring ring-gray-300 focus:border-blue-300 active:bg-gray-100 active:text-black transition ease-in-out duration-150'} rounded-r-md leading-5" ${page === totalPages ? 'aria-disabled="true"' : ''}>
                                <span class="sr-only">Next</span>
                                <svg class="w-5 h-5" fill="currentColor" viewBox="0 0 20 20" aria-hidden="true">
                                    <path fill-rule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clip-rule="evenodd" />
                                </svg>
                            </button>
                        </span>
                    </div>
                </div>
            </div>`;
        }
    } else {
        html += `<div class="p-3 bg-yellow-50 text-yellow-800 border border-yellow-200 rounded-md text-sm">Belum ada program terdaftar di wilayah ini.</div>`;
    }
    
    infoDetail.innerHTML = html;
};

window.showProgramDetailModal = function(id, tanggal) {
    const p = (window.regionProgramsData || []).find(prog => prog.id == id);
    if (!p) return;

    document.getElementById('pd-title').textContent = p.nama_program || '-';
    document.getElementById('pd-tim-kerja').textContent = p.tim_kerja || '-';
    
    document.getElementById('pd-tanggal').textContent = tanggal || '-';
    document.getElementById('pd-deskripsi').textContent = p.deskripsi || '-';
    
    const fileContainer = document.getElementById('pd-file-container');
    const fileContent = document.getElementById('pd-file-content');
    
    if (p.file_path) {
        fileContainer.classList.remove('hidden');
        const ext = p.file_path.split('.').pop().toLowerCase();
        const url = `/storage/${p.file_path}`;
        const isImage = ['jpg', 'jpeg', 'png', 'webp'].includes(ext);
        
        if (isImage) {
            fileContent.innerHTML = `<img src="${url}" alt="File dukung" class="max-w-full md:max-w-lg rounded-md border border-gray-200">`;
        } else {
            fileContent.innerHTML = `<a href="${url}" target="_blank" download class="inline-flex items-center px-4 py-2 bg-blue-50 text-blue-700 rounded-md hover:bg-blue-100 text-sm font-medium">
                <svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5 mr-2" viewBox="0 0 20 20" fill="currentColor">
                    <path fill-rule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clip-rule="evenodd" />
                </svg>
                Unduh File (${ext.toUpperCase()})
            </a>`;
        }
    } else {
        fileContainer.classList.add('hidden');
        fileContent.innerHTML = '';
    }
    
    window.dispatchEvent(new CustomEvent('open-modal', { detail: 'program-detail' }));
};
</script>
